using System.Text;
using System.Text.Json;
using System.Security.Cryptography;
using System.Net;
using Arcoll.WinUI3.Services.BackupCenter;
var sandbox=Path.Combine(Path.GetTempPath(),"tidigital-backup-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(sandbox);var passed=0;
void Check(bool value,string label){if(!value)throw new Exception("FAIL "+label);Console.WriteLine("PASS "+label);passed++;}
void Reject(Action action,string label){try{action();}catch(IOException){Check(true,label);return;}throw new Exception("FAIL "+label);}
try{
 foreach(var path in new[]{"../x","/x","a//b","a\\b","C:foo","CON.txt","a/..","a./b","x?y","file "})Reject(()=>BackupSafety.Relative(path),"unsafe path "+path);
 Check(BackupSafety.Relative("relatórios/ação.txt")=="relatórios/ação.txt","unicode safe relative");Check(!BackupSafety.Inside(Path.Combine(sandbox,"data2"),Path.Combine(sandbox,"data")),"path boundary");Reject(()=>BackupSafety.SafeChild(sandbox,"..","escape"),"restore path containment");Check(BackupSafety.Excluded("cache/a.tmp",["*.tmp"]),"glob exclusion");Check(BackupSafety.LiveDatabase("production.mdf"),"live database blocked");
 var src=Path.Combine(sandbox,"source");Directory.CreateDirectory(src);File.WriteAllText(Path.Combine(src,"a.txt"),"primeira versão α");File.WriteAllText(Path.Combine(src,"ignored.tmp"),"ignore");File.WriteAllBytes(Path.Combine(src,"empty.txt"),[]);Directory.CreateDirectory(Path.Combine(src,"nested"));File.WriteAllText(Path.Combine(src,"nested","b.txt"),"outro arquivo");
 var settings=new BackupSettings([src],"","manual",60,"22:00","America/Belem",["*.tmp"],10,0,30,1440);var plan=new BackupPlan(new string('a',32),"Teste","cloud",1,true,false,settings,new string('b',64),1,2,3);var remote=new Fake();var work=Path.Combine(sandbox,"work");var restore=Path.Combine(sandbox,"restored");var engine=new BackupExecutor(remote,work,restore);
 BackupOperation Op(string kind,BackupPlan? p=null,string? source=null,string[]? selection=null)=>new(Guid.NewGuid().ToString("N"),kind,source,selection??[],p??plan,new string('c',64),20*1048576);
 var first=Op("backup");await engine.RunAsync(first,CancellationToken.None);Check(remote.Summaries[first.Id].Files==3,"cloud includes nested and zero file, excludes temp");Check(remote.Summaries[first.Id].Errors==0,"first backup complete");Check(remote.Objects.Count==3,"content objects stored");Check(remote.Objects.Values.Any(b=>b.Length==0),"empty cloud object");Check(remote.Files[first.Id].Any(f=>f.Relative=="nested/b.txt"),"nested manifest path");
 var before=File.ReadAllText(Path.Combine(src,"a.txt"));var same=Op("backup");await engine.RunAsync(same,CancellationToken.None);Check(remote.Summaries[same.Id].Unchanged==3&&remote.Summaries[same.Id].Bytes==0,"incremental reuses content");File.WriteAllText(Path.Combine(src,"a.txt"),"segunda versão");File.Delete(Path.Combine(src,"nested","b.txt"));var changed=Op("backup");await engine.RunAsync(changed,CancellationToken.None);Check(remote.Files[first.Id].Count==3&&remote.Files[changed.Id].Count==2,"source deletion preserves old point");Check(remote.Objects.Count==4,"changed file creates new version");
 var recover=Op("restore",source:first.Id);await engine.RunAsync(recover,CancellationToken.None);Check(File.ReadAllText(Path.Combine(restore,recover.Id,"Origem1","a.txt"))==before,"restore original version");Check(File.ReadAllText(Path.Combine(src,"a.txt"))=="segunda versão","restore never overwrites source");Check(File.Exists(Path.Combine(restore,recover.Id,"Origem1","nested","b.txt")),"deleted file recoverable");Check(remote.Summaries[recover.Id].Errors==0,"restore sha256 succeeds");
 var verify=Op("verify",source:first.Id);await engine.RunAsync(verify,CancellationToken.None);Check(remote.Summaries[verify.Id].Files==3&&!Directory.Exists(Path.Combine(restore,verify.Id)),"verify reads all without restore output");
 var one=remote.Files[first.Id].First(f=>f.Relative=="a.txt");var selected=Op("restore",source:first.Id,selection:[one.PathHash]);await engine.RunAsync(selected,CancellationToken.None);Check(Directory.GetFiles(Path.Combine(restore,selected.Id),"*",SearchOption.AllDirectories).Length==1,"selection restricts restoration");
 remote.Objects[one.Digest]=Encoding.UTF8.GetBytes("damaged");var corrupt=Op("restore",source:first.Id,selection:[one.PathHash]);await engine.RunAsync(corrupt,CancellationToken.None);Check(remote.Summaries[corrupt.Id].Errors==1,"corrupt content reported");Check(!Directory.GetFiles(Path.Combine(restore,corrupt.Id),"*",SearchOption.AllDirectories).Any(),"corrupt partial never delivered");remote.Objects[one.Digest]=Encoding.UTF8.GetBytes(before);
 File.WriteAllText(Path.Combine(src,"production.mdf"),"live database");var partial=Op("backup");await engine.RunAsync(partial,CancellationToken.None);Check(remote.Summaries[partial.Id].Errors==1&&!remote.Files[partial.Id].Any(f=>f.Relative.EndsWith("mdf")),"live DB makes backup partial");File.Delete(Path.Combine(src,"production.mdf"));
 var localPlan=plan with{Target="local",ConnectionId=null,Settings=settings with{Destination=Path.Combine(sandbox,"destination")}};var local=Op("backup",localPlan);await engine.RunAsync(local,CancellationToken.None);Check(remote.Summaries[local.Id].Errors==0,"local CAS backup complete");Check(Directory.GetFiles(localPlan.Settings.Destination,"*.json",SearchOption.AllDirectories).Length>=2,"independent local manifest stored");var localRestore=Op("restore",localPlan,local.Id);await engine.RunAsync(localRestore,CancellationToken.None);Check(File.ReadAllText(Path.Combine(restore,localRestore.Id,"Origem1","a.txt"))=="segunda versão","local restore validates bytes");
 Reject(()=>new BackupRepository(localPlan with{Settings=settings with{Destination=Path.Combine(src,"backup")}}),"nested destination rejected");var unrelated=localPlan with{Id=new string('d',32)};var repo=new BackupRepository(unrelated);Check(repo is not null,"separate plan repository");
 using var cancelled=new CancellationTokenSource();cancelled.Cancel();var cancelledOk=false;try{await engine.RunAsync(Op("backup"),cancelled.Token);}catch(OperationCanceledException){cancelledOk=true;}Check(cancelledOk,"cancellation propagated");
 remote.BadManifest=true;var invalid=Op("verify",source:first.Id);try{await engine.RunAsync(invalid,CancellationToken.None);}catch(IOException){}Check(remote.Failed.Contains(invalid.Id),"tampered manifest fails before reading objects");remote.BadManifest=false;
 var handler=new Probe();using(var http=new BackupHttpClient(new("https://example.test","fp","SITE1","secret"),handler)){await http.StateAsync(CancellationToken.None);Check(handler.Action=="?action=agent-state"&&handler.Key=="secret","agent API credentials restricted to configured endpoint");Check(handler.Body=="{}","state request contains no credentials in JSON");}
 Console.WriteLine($"{passed} assertions passed");
}finally{Directory.Delete(sandbox,true);}
sealed class Probe:HttpMessageHandler{public string Action="",Key="",Body="";protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){Action=r.RequestUri!.Query;Key=r.Headers.GetValues("X-Arcoll-Key").Single();Body=await r.Content!.ReadAsStringAsync(ct);return new(HttpStatusCode.OK){Content=new StringContent("{\"ok\":true}")};}}
sealed class Fake:IBackupRemote{
 public Dictionary<string,byte[]> Objects=[];public Dictionary<string,List<BackupFile>> Files=[];public Dictionary<string,BackupPlan> Plans=[];public Dictionary<string,BackupSummary> Summaries=[];public HashSet<string> Failed=[];public bool BadManifest;private Dictionary<string,MemoryStream> uploads=[];
 public Task<BackupOperation?> NextAsync(string runner,CancellationToken ct)=>Task.FromResult<BackupOperation?>(null);public Task<JsonElement> StateAsync(CancellationToken ct)=>Task.FromResult(JsonSerializer.SerializeToElement(new{ok=true}));public Task ProgressAsync(BackupOperation op,BackupSummary summary,CancellationToken ct){ct.ThrowIfCancellationRequested();return Task.CompletedTask;}
 public Task<UploadReply> BeginAsync(BackupOperation op,string digest,string md5,long size,CancellationToken ct){if(Objects.ContainsKey(digest))return Task.FromResult(new UploadReply(true,size,null));if(size==0){Objects[digest]=[];return Task.FromResult(new UploadReply(true,0,null));}uploads[digest]=new();return Task.FromResult(new UploadReply(false,0,digest,7));}
 public Task<UploadReply> ChunkAsync(BackupOperation op,string digest,string md5,string upload,long offset,byte[] data,CancellationToken ct){var stream=uploads[digest];if(stream.Position!=offset)throw new Exception("offset");stream.Write(data);Objects[digest]=stream.ToArray();var expected=Convert.ToHexString(SHA256.HashData(Objects[digest])).ToLowerInvariant();var done=expected==digest;return Task.FromResult(new UploadReply(done,stream.Length,digest,7));}
 public Task FilesAsync(BackupOperation op,IReadOnlyList<BackupFile> files,CancellationToken ct){if(!Files.ContainsKey(op.Id))Files[op.Id]=[];Files[op.Id].AddRange(files);Plans[op.Id]=op.Plan;return Task.CompletedTask;}
 public Task<FinishReply> FinishAsync(BackupOperation op,BackupSummary summary,CancellationToken ct){if(!Files.ContainsKey(op.Id))Files[op.Id]=[];Plans[op.Id]=op.Plan;Summaries[op.Id]=summary;var canonical=JsonSerializer.Serialize(new BackupManifest("tidigital.backup.v1",Files[op.Id]),BackupJson.Options);return Task.FromResult(new FinishReply(canonical,BackupSafety.HashText(canonical)));}
 public Task FailAsync(BackupOperation op,BackupSummary summary,CancellationToken ct){Failed.Add(op.Id);return Task.CompletedTask;}
 public Task<ManifestReply> ManifestAsync(BackupOperation op,CancellationToken ct){var canonical=JsonSerializer.Serialize(new BackupManifest("tidigital.backup.v1",Files[op.SourceRun!]),BackupJson.Options);return Task.FromResult(new ManifestReply(canonical,BadManifest?new string('0',64):BackupSafety.HashText(canonical),Plans[op.SourceRun!],op.Selection));}
 public Task<Stream> DownloadAsync(BackupOperation op,BackupFile file,CancellationToken ct)=>Task.FromResult<Stream>(new MemoryStream(Objects[file.Digest]));public Task FinishOperationAsync(BackupOperation op,BackupSummary summary,CancellationToken ct){Summaries[op.Id]=summary;return Task.CompletedTask;}public void Dispose(){}
}
